#pragma once
// v67 (B156): meowest's draft (3-4 bodies), shop order and bag from its panel games, generated by tools/profiles.py build --base v66.
// v68 (B164): three bodies draft Aynir's Heart of Ruin, Ryth, Marcella (arena 62% vs v67 on the 21 three-pick maps).
// v69 (B167): four picks take Vendetta for Vesper, five picks Varg for Vendetta (nonreg 53% vs v68, submitted gems +48 ± 7 over 3,328 games).
#include <cambc.h>
#include <optional>
#include <vector>

inline std::vector<cambc::champion_draft> profile_picks(std::size_t size) {
    using cambc::champion_draft;
    switch (size) {
    case 3: return {champion_draft::heart_of_ruin, champion_draft::ryth, champion_draft::marcella};
    case 4: return {champion_draft::heart_of_ruin, champion_draft::ryth, champion_draft::marcella, champion_draft::vendetta};
    case 5: return {champion_draft::marcella, champion_draft::heart_of_ruin, champion_draft::vesper_vale, champion_draft::ryth, champion_draft::varg};
    default: return {};
    }
}

struct profile_build { std::vector<cambc::item_type> order; float health_share; cambc::item_type health; };
inline std::optional<profile_build> profile_build_for(cambc::champion_type c) {
    using cambc::item_type;
    using cambc::champion_type;
    if (c == champion_type::heart_of_ruin) return profile_build{{item_type::jungle_shard_of_focus, item_type::prospector_shard_of_health, item_type::durability_shard_of_health, item_type::bruiser_shard_of_focus}, 0.0f, item_type::bruiser_shard_of_health};
    if (c == champion_type::marcella) return profile_build{{item_type::jungle_shard_of_focus, item_type::prospector_shard_of_health, item_type::durability_shard_of_health, item_type::bruiser_shard_of_focus}, 0.0f, item_type::bruiser_shard_of_health};
    if (c == champion_type::ryth) return profile_build{{item_type::prospector_shard_of_health, item_type::durability_shard_of_health, item_type::jungle_shard_of_strength, item_type::bruiser_shard_of_strength}, 0.0f, item_type::bruiser_shard_of_health};
    if (c == champion_type::vendetta) return profile_build{{item_type::prospector_shard_of_health, item_type::durability_shard_of_health, item_type::jungle_shard_of_strength, item_type::bruiser_shard_of_strength}, 0.0f, item_type::bruiser_shard_of_health};
    if (c == champion_type::varg) return profile_build{{item_type::prospector_shard_of_health, item_type::durability_shard_of_health, item_type::jungle_shard_of_strength, item_type::bruiser_shard_of_strength}, 0.0f, item_type::bruiser_shard_of_health};
    if (c == champion_type::vesper_vale) return profile_build{{item_type::prospector_shard_of_strength, item_type::durability_shard_of_health, item_type::jungle_shard_of_strength, item_type::bruiser_shard_of_strength}, 0.0f, item_type::bruiser_shard_of_health};
    return std::nullopt;
}

constexpr int profile_bag = 36;
